33 #define _REQUIRE_PARALLEL_LVALUE_ITERATOR(_Iter)                                                                     \
34     static_assert(_Is_ranges_fwd_iter_v<_Iter> && is_lvalue_reference_v<_Iter_ref_t<_Iter>>,                         \
35         "Parallel specialized <memory> algorithms require the iterator type to be forward iterator and dereference " \
36         "to lvalues.")
