38 _EXPORT_STD template <class _ExPo, class _FwdIt, class _NoThrowFwdIt, _Enable_if_execution_policy_t<_ExPo> = 0>
39 _NoThrowFwdIt uninitialized_copy(_ExPo&&, const _FwdIt _First, const _FwdIt _Last, _NoThrowFwdIt _Dest) noexcept
40 /* terminates */ {
41     // copy [_First, _Last) to raw [_Dest, ...)
42     // not parallelized at present
43     _REQUIRE_PARALLEL_ITERATOR(_FwdIt);
44     _REQUIRE_PARALLEL_LVALUE_ITERATOR(_NoThrowFwdIt);
45 
46     return _STD uninitialized_copy(_First, _Last, _Dest);
47 }
48 #endif // _HAS_CXX17
