50 #if _HAS_CXX20
51 namespace ranges {
52     _EXPORT_STD template <class _In, class _Out>
53         using uninitialized_copy_result = in_out_result<_In, _Out>;
54 
55     class _Uninitialized_copy_fn {
56     public:
57         template <input_iterator _It, sentinel_for<_It> _Se, _No_throw_forward_iterator _Out,
58             _No_throw_sentinel_for<_Out> _OSe>
59             requires constructible_from<iter_value_t<_Out>, iter_reference_t<_It>>
60         _STATIC_CALL_OPERATOR uninitialized_copy_result<_It, _Out> operator()(
61             _It _First1, _Se _Last1, _Out _First2, _OSe _Last2) _CONST_CALL_OPERATOR {
62             _STD _Adl_verify_range(_First1, _Last1);
63             _STD _Adl_verify_range(_First2, _Last2);
64             auto _UResult = _Uninitialized_copy_unchecked(_RANGES _Unwrap_iter<_Se>(_STD move(_First1)),
65                 _RANGES _Unwrap_sent<_It>(_STD move(_Last1)), _RANGES _Unwrap_iter<_OSe>(_STD move(_First2)),
66                 _RANGES _Unwrap_sent<_Out>(_STD move(_Last2)));
67 
68             _STD _Seek_wrapped(_First1, _STD move(_UResult.in));
69             _STD _Seek_wrapped(_First2, _STD move(_UResult.out));
70             return { _STD move(_First1), _STD move(_First2) };
71         }
72 
73         template <input_range _Rng1, _No_throw_forward_range _Rng2>
74             requires constructible_from<range_value_t<_Rng2>, range_reference_t<_Rng1>>
75         _STATIC_CALL_OPERATOR uninitialized_copy_result<borrowed_iterator_t<_Rng1>, borrowed_iterator_t<_Rng2>>
76             operator()(_Rng1&& _Range1, _Rng2&& _Range2) _CONST_CALL_OPERATOR {
77             auto _First1 = _RANGES begin(_Range1);
78             auto _UResult = _Uninitialized_copy_unchecked(_RANGES _Unwrap_range_iter<_Rng1>(_STD move(_First1)),
79                 _Uend(_Range1), _Ubegin(_Range2), _Uend(_Range2));
80 
81             _STD _Seek_wrapped(_First1, _STD move(_UResult.in));
82             return { _STD move(_First1), _RANGES _Rewrap_iterator(_Range2, _STD move(_UResult.out)) };
83         }
84 
85     private:
86         template <class _It, class _Se, class _Out, class _OSe>
87         _NODISCARD static uninitialized_copy_result<_It, _Out> _Uninitialized_copy_unchecked(
88             _It _IFirst, _Se _ILast, _Out _OFirst, _OSe _OLast) {
89             _STL_INTERNAL_STATIC_ASSERT(input_iterator<_It>);
90             _STL_INTERNAL_STATIC_ASSERT(sentinel_for<_Se, _It>);
91             _STL_INTERNAL_STATIC_ASSERT(_No_throw_forward_iterator<_Out>);
92             _STL_INTERNAL_STATIC_ASSERT(_No_throw_sentinel_for<_OSe, _Out>);
93             _STL_INTERNAL_STATIC_ASSERT(constructible_from<iter_value_t<_Out>, iter_reference_t<_It>>);
94 
95             constexpr bool _Is_sized1 = sized_sentinel_for<_Se, _It>;
96             constexpr bool _Is_sized2 = sized_sentinel_for<_OSe, _Out>;
97             if constexpr (_Iter_copy_cat<_It, _Out>::_Bitcopy_constructible
98                 && _Sized_or_unreachable_sentinel_for<_Se, _It>
99                 && _Sized_or_unreachable_sentinel_for<_OSe, _Out>) {
100                 if constexpr (_Is_sized1 && _Is_sized2) {
101                     return _RANGES _Copy_memcpy_common(_IFirst, _RANGES next(_IFirst, _STD move(_ILast)), _OFirst,
102                         _RANGES next(_OFirst, _STD move(_OLast)));
103                 }
104                 else if constexpr (_Is_sized1) {
105                     return _RANGES _Copy_memcpy_distance(
106                         _IFirst, _OFirst, _IFirst, _RANGES next(_IFirst, _STD move(_ILast)));
107                 }
108                 else if constexpr (_Is_sized2) {
109                     return _RANGES _Copy_memcpy_distance(
110                         _IFirst, _OFirst, _OFirst, _RANGES next(_OFirst, _STD move(_OLast)));
111                 }
112                 else {
113                     _STL_ASSERT(false, "Tried to uninitialized_copy two ranges with unreachable sentinels");
114                 }
115             }
116             else {
117                 _Uninitialized_backout _Backout{ _STD move(_OFirst) };
118 
119                 for (; _IFirst != _ILast && _Backout._Last != _OLast; ++_IFirst) {
120                     _Backout._Emplace_back(*_IFirst);
121                 }
122 
123                 return { _STD move(_IFirst), _Backout._Release() };
124             }
125         }
126     };
127 
128     _EXPORT_STD inline constexpr _Uninitialized_copy_fn uninitialized_copy;
129 } // namespace ranges
130 #endif // _HAS_CXX20
