132 _EXPORT_STD template <class _InIt, class _Diff, class _NoThrowFwdIt>
133 _NoThrowFwdIt uninitialized_copy_n(const _InIt _First, const _Diff _Count_raw, _NoThrowFwdIt _Dest) {
134     // copy [_First, _First + _Count) to [_Dest, ...)
135     _Algorithm_int_t<_Diff> _Count = _Count_raw;
136     if (_Count <= 0) {
137         return _Dest;
138     }
139 
140     auto _UFirst = _STD _Get_unwrapped_n(_First, _Count);
141     auto _UDest = _STD _Get_unwrapped_n(_Dest, _Count);
142     if constexpr (_Iter_copy_cat<decltype(_UFirst), decltype(_UDest)>::_Bitcopy_constructible) {
143         _UDest = _STD _Copy_memmove_n(_UFirst, static_cast<size_t>(_Count), _UDest);
144     }
145     else {
146         _Uninitialized_backout<decltype(_UDest)> _Backout{ _UDest };
147 
148         for (; _Count > 0; --_Count, (void) ++_UFirst) {
149             _Backout._Emplace_back(*_UFirst);
150         }
151 
152         _UDest = _Backout._Release();
153     }
154 
155     _STD _Seek_wrapped(_Dest, _UDest);
156     return _Dest;
157 }
