167     _REQUIRE_PARALLEL_LVALUE_ITERATOR(_NoThrowFwdIt);
168 
169     _Algorithm_int_t<_Diff> _Count = _Count_raw;
170     return _STD uninitialized_copy_n(_First, _Count, _Dest);
171 }
