176     _EXPORT_STD template <class _In, class _Out>
177         using uninitialized_copy_n_result = in_out_result<_In, _Out>;
178 
179     class _Uninitialized_copy_n_fn {
180     public:
181         template <input_iterator _It, _No_throw_forward_iterator _Out, _No_throw_sentinel_for<_Out> _OSe>
182             requires constructible_from<iter_value_t<_Out>, iter_reference_t<_It>>
183         _STATIC_CALL_OPERATOR uninitialized_copy_n_result<_It, _Out> operator()(
184             _It _First1, iter_difference_t<_It> _Count, _Out _First2, _OSe _Last2) _CONST_CALL_OPERATOR {
185             if (_Count <= 0) {
186                 return { _STD move(_First1), _STD move(_First2) };
187             }
188 
189             _STD _Adl_verify_range(_First2, _Last2);
190             auto _IFirst = _STD _Get_unwrapped_n(_STD move(_First1), _Count);
191             auto _OFirst = _RANGES _Unwrap_iter<_OSe>(_STD move(_First2));
192             auto _OLast = _RANGES _Unwrap_sent<_Out>(_STD move(_Last2));
193             if constexpr (_Iter_copy_cat<_It, _Out>::_Bitcopy_constructible
194                 && _Sized_or_unreachable_sentinel_for<_OSe, _Out>) {
195                 if constexpr (sized_sentinel_for<_OSe, _Out>) {
196                     auto _UResult = _RANGES _Copy_memcpy_common(
197                         _IFirst, _IFirst + _Count, _OFirst, _RANGES next(_OFirst, _STD move(_OLast)));
198                     _IFirst = _STD move(_UResult.in);
199                     _OFirst = _STD move(_UResult.out);
200                 }
201                 else {
202                     auto _UResult = _RANGES _Copy_memcpy_count(_IFirst, _OFirst, static_cast<size_t>(_Count));
203                     _IFirst = _STD move(_UResult.in);
204                     _OFirst = _STD move(_UResult.out);
205                 }
206             }
207             else {
208                 _Uninitialized_backout _Backout{ _STD move(_OFirst) };
209 
210                 for (; _Count > 0 && _Backout._Last != _OLast; --_Count, (void) ++_IFirst) {
211                     _Backout._Emplace_back(*_IFirst);
212                 }
213 
214                 _OFirst = _Backout._Release();
215             }
216 
217             _STD _Seek_wrapped(_First1, _STD move(_IFirst));
218             _STD _Seek_wrapped(_First2, _STD move(_OFirst));
219             return { _STD move(_First1), _STD move(_First2) };
220         }
221     };
222 
223     _EXPORT_STD inline constexpr _Uninitialized_copy_n_fn uninitialized_copy_n;
224 } // namespace ranges
