228 _EXPORT_STD template <class _InIt, class _NoThrowFwdIt>
229 _NoThrowFwdIt uninitialized_move(const _InIt _First, const _InIt _Last, _NoThrowFwdIt _Dest) {
230     // move [_First, _Last) to raw [_Dest, ...)
231     _STD _Adl_verify_range(_First, _Last);
232     const auto _UFirst = _STD _Get_unwrapped(_First);
233     const auto _ULast = _STD _Get_unwrapped(_Last);
234     const auto _UDest = _STD _Get_unwrapped_n(_Dest, _STD _Idl_distance<_InIt>(_UFirst, _ULast));
235     _STD _Seek_wrapped(_Dest, _STD _Uninitialized_move_unchecked(_UFirst, _ULast, _UDest));
236     return _Dest;
237 }
