287 _EXPORT_STD template <class _InIt, class _Diff, class _NoThrowFwdIt>
288 pair<_InIt, _NoThrowFwdIt> uninitialized_move_n(_InIt _First, const _Diff _Count_raw, _NoThrowFwdIt _Dest) {
289     // move [_First, _First + _Count) to [_Dest, ...)
290     _Algorithm_int_t<_Diff> _Count = _Count_raw;
291     if (_Count <= 0) {
292         return { _First, _Dest };
293     }
294 
295     auto _UFirst = _STD _Get_unwrapped_n(_First, _Count);
296     auto _UDest = _STD _Get_unwrapped_n(_Dest, _Count);
297     if constexpr (_Iter_move_cat<decltype(_UFirst), decltype(_UDest)>::_Bitcopy_constructible) {
298         _UDest = _STD _Copy_memmove_n(_UFirst, static_cast<size_t>(_Count), _UDest);
299         _UFirst += _Count;
300     }
301     else {
302         _Uninitialized_backout<decltype(_UDest)> _Backout{ _UDest };
303 
304         for (; _Count > 0; --_Count, (void) ++_UFirst) {
305             _Backout._Emplace_back(_STD move(*_UFirst));
306         }
307 
308         _UDest = _Backout._Release();
309     }
310 
311     _STD _Seek_wrapped(_Dest, _UDest);
312     _STD _Seek_wrapped(_First, _UFirst);
313     return { _First, _Dest };
314 }
315 
