319         _ExPo&&, const _FwdIt _First, const _Diff _Count_raw, _NoThrowFwdIt _Dest) noexcept /* terminates */ {
320     // move [_First, _First + _Count) to raw [_Dest, ...)
321     // not parallelized at present
322     _REQUIRE_PARALLEL_ITERATOR(_FwdIt);
323     _REQUIRE_PARALLEL_LVALUE_ITERATOR(_NoThrowFwdIt);
324 
325     _Algorithm_int_t<_Diff> _Count = _Count_raw;
326     return _STD uninitialized_move_n(_First, _Count, _Dest);
327 }
