329 _EXPORT_STD template <class _ExPo, class _NoThrowFwdIt, class _Tval, _Enable_if_execution_policy_t<_ExPo> = 0>
330 void uninitialized_fill(_ExPo&&, const _NoThrowFwdIt _First, const _NoThrowFwdIt _Last, const _Tval& _Val) noexcept
331 /* terminates */ {
332     // copy _Val throughout raw [_First, _Last)
333     // not parallelized at present
334     _REQUIRE_PARALLEL_LVALUE_ITERATOR(_NoThrowFwdIt);
