345     class _Uninitialized_move_n_fn {
346     public:
347         template <input_iterator _It, _No_throw_forward_iterator _Out, _No_throw_sentinel_for<_Out> _OSe>
348             requires constructible_from<iter_value_t<_Out>, iter_rvalue_reference_t<_It>>
349         _STATIC_CALL_OPERATOR uninitialized_move_n_result<_It, _Out> operator()(
350             _It _First1, iter_difference_t<_It> _Count, _Out _First2, _OSe _Last2) _CONST_CALL_OPERATOR {
351             if (_Count <= 0) {
352                 return { _STD move(_First1), _STD move(_First2) };
353             }
354 
355             _STD _Adl_verify_range(_First2, _Last2);
356             auto _IFirst = _STD _Get_unwrapped_n(_STD move(_First1), _Count);
357             auto _OFirst = _RANGES _Unwrap_iter<_OSe>(_STD move(_First2));
358             const auto _OLast = _RANGES _Unwrap_sent<_Out>(_STD move(_Last2));
359             if constexpr (_Iter_move_cat<_It, _Out>::_Bitcopy_constructible
360                 && _Sized_or_unreachable_sentinel_for<_OSe, _Out>) {
361                 if constexpr (sized_sentinel_for<_OSe, _Out>) {
362                     auto _UResult = _RANGES _Copy_memcpy_common(
363                         _IFirst, _IFirst + _Count, _OFirst, _RANGES next(_OFirst, _STD move(_OLast)));
364                     _IFirst = _STD move(_UResult.in);
365                     _OFirst = _STD move(_UResult.out);
366                 }
367                 else {
368                     auto _UResult = _RANGES _Copy_memcpy_count(_IFirst, _OFirst, static_cast<size_t>(_Count));
369                     _IFirst = _STD move(_UResult.in);
370                     _OFirst = _STD move(_UResult.out);
371                 }
372             }
373             else {
374                 _Uninitialized_backout _Backout{ _STD move(_OFirst) };
375 
376                 for (; _Count > 0 && _Backout._Last != _OLast; --_Count, (void) ++_IFirst) {
377                     _Backout._Emplace_back(_RANGES iter_move(_IFirst));
378                 }
379 
380                 _OFirst = _Backout._Release();
381             }
382 
383             _STD _Seek_wrapped(_First1, _STD move(_IFirst));
384             _STD _Seek_wrapped(_First2, _STD move(_OFirst));
385             return { _STD move(_First1), _STD move(_First2) };
386         }
387     };
