391     class _Uninitialized_fill_fn {
392     public:
393         template <_No_throw_forward_iterator _It, _No_throw_sentinel_for<_It> _Se, class _Ty>
394             requires constructible_from<iter_value_t<_It>, const _Ty&>
395         _STATIC_CALL_OPERATOR _It operator()(_It _First, _Se _Last, const _Ty& _Val) _CONST_CALL_OPERATOR {
396             _STD _Adl_verify_range(_First, _Last);
397             auto _UResult = _Uninitialized_fill_unchecked(
398                 _RANGES _Unwrap_iter<_Se>(_STD move(_First)), _RANGES _Unwrap_sent<_It>(_STD move(_Last)), _Val);
399 
400             _STD _Seek_wrapped(_First, _STD move(_UResult));
401             return _First;
402         }
403 
404         template <_No_throw_forward_range _Rng, class _Ty>
405             requires constructible_from<range_value_t<_Rng>, const _Ty&>
406         _STATIC_CALL_OPERATOR borrowed_iterator_t<_Rng> operator()(
407             _Rng&& _Range, const _Ty& _Val) _CONST_CALL_OPERATOR {
408             return _RANGES _Rewrap_iterator(
409                 _Range, _Uninitialized_fill_unchecked(_Ubegin(_Range), _Uend(_Range), _Val));
410         }
411 
412     private:
413         template <class _It, class _Se, class _Ty>
414         _NODISCARD static _It _Uninitialized_fill_unchecked(_It _OFirst, _Se _OLast, const _Ty& _Val) {
415             _STL_INTERNAL_STATIC_ASSERT(_No_throw_forward_iterator<_It>);
416             _STL_INTERNAL_STATIC_ASSERT(_No_throw_sentinel_for<_Se, _It>);
417             _STL_INTERNAL_STATIC_ASSERT(constructible_from<iter_value_t<_It>, const _Ty&>);
418 
419             if constexpr (_Fill_memset_is_safe<_It, _Ty>) {
420                 const auto _OFinal = _RANGES next(_OFirst, _STD move(_OLast));
421                 _STD _Fill_memset(_OFirst, _Val, static_cast<size_t>(_OFinal - _OFirst));
422                 return _OFinal;
423             }
424             else {
425                 if constexpr (_Fill_zero_memset_is_safe<_It, _Ty>) {
426                     if (_STD _Is_all_bits_zero(_Val)) {
427                         const auto _OFinal = _RANGES next(_OFirst, _STD move(_OLast));
428                         _STD _Fill_zero_memset(_OFirst, static_cast<size_t>(_OFinal - _OFirst));
429                         return _OFinal;
430                     }
431                 }
432 
433                 _Uninitialized_backout _Backout{ _STD move(_OFirst) };
434 
435                 while (_Backout._Last != _OLast) {
436                     _Backout._Emplace_back(_Val);
437                 }
438 
439                 return _Backout._Release();
440             }
441         }
442     };
443 
444     _EXPORT_STD inline constexpr _Uninitialized_fill_fn uninitialized_fill;
445 } // namespace ranges
446 #endif // _HAS_CXX20
