448 _EXPORT_STD template <class _NoThrowFwdIt, class _Diff, class _Tval>
449 _NoThrowFwdIt uninitialized_fill_n(_NoThrowFwdIt _First, const _Diff _Count_raw, const _Tval& _Val) {
450     // copy _Count copies of _Val to raw _First
451     _Algorithm_int_t<_Diff> _Count = _Count_raw;
452     if (_Count <= 0) {
453         return _First;
454     }
455 
456     auto _UFirst = _STD _Get_unwrapped_n(_First, _Count);
457     if constexpr (_Fill_memset_is_safe<decltype(_UFirst), _Tval>) {
458         _STD _Fill_memset(_UFirst, _Val, static_cast<size_t>(_Count));
459         _UFirst += _Count;
460     }
461     else {
462         if constexpr (_Fill_zero_memset_is_safe<decltype(_UFirst), _Tval>) {
463             if (_STD _Is_all_bits_zero(_Val)) {
464                 _STD _Fill_zero_memset(_UFirst, static_cast<size_t>(_Count));
465                 _STD _Seek_wrapped(_First, _UFirst + _Count);
466                 return _First;
467             }
468         }
469 
470         _Uninitialized_backout<decltype(_UFirst)> _Backout{ _UFirst };
471 
472         for (; _Count > 0; --_Count) {
473             _Backout._Emplace_back(_Val);
474         }
475 
476         _UFirst = _Backout._Release();
477     }
478 
479     _STD _Seek_wrapped(_First, _UFirst);
480     return _First;
481 }
