1130 class __declspec(novtable) _Ref_count_base { // common code for reference counting
1131 private:
1132 #ifdef _M_CEE_PURE
1133     // permanent workaround to avoid mentioning _purecall in msvcurt.lib, ptrustu.lib, or other support libs
1134     virtual void _Destroy() noexcept {
1135         _CSTD abort();
1136     }
1137 
1138     virtual void _Delete_this() noexcept {
1139         _CSTD abort();
1140     }
1141 #else // ^^^ defined(_M_CEE_PURE) / !defined(_M_CEE_PURE) vvv
1142     virtual void _Destroy() noexcept = 0; // destroy managed resource
1143     virtual void _Delete_this() noexcept = 0; // destroy self
1144 #endif // ^^^ !defined(_M_CEE_PURE) ^^^
1145 
1146     _Atomic_counter_t _Uses = 1;
1147     _Atomic_counter_t _Weaks = 1;
1148 
1149 protected:
1150     constexpr _Ref_count_base() noexcept = default; // non-atomic initializations
1151 
1152 public:
1153     _Ref_count_base(const _Ref_count_base&) = delete;
1154     _Ref_count_base& operator=(const _Ref_count_base&) = delete;
1155 
1156     virtual ~_Ref_count_base() noexcept {} // TRANSITION, should be non-virtual
1157 
1158     bool _Incref_nz() noexcept { // increment use count if not zero, return true if successful
1159         auto& _Volatile_uses = reinterpret_cast<volatile long&>(_Uses);
1160 #ifdef _M_CEE_PURE
1161         long _Count = *_Atomic_address_as<const long>(&_Volatile_uses);
1162 #else
1163         long _Count = __iso_volatile_load32(reinterpret_cast<volatile int*>(&_Volatile_uses));
1164 #endif
1165         while (_Count != 0) {
1166             const long _Old_value = _INTRIN_RELAXED(_InterlockedCompareExchange)(&_Volatile_uses, _Count + 1, _Count);
1167             if (_Old_value == _Count) {
1168                 return true;
1169             }
1170 
1171             _Count = _Old_value;
1172         }
1173 
1174         return false;
1175     }
1176 
1177     void _Incref() noexcept { // increment use count
1178         _MT_INCR(_Uses);
1179     }
1180 
1181     void _Incwref() noexcept { // increment weak reference count
1182         _MT_INCR(_Weaks);
1183     }
1184 
1185     void _Decref() noexcept { // decrement use count
1186         if (_MT_DECR(_Uses) == 0) {
1187             _Destroy();
1188             _Decwref();
1189         }
1190     }
1191 
1192     void _Decwref() noexcept { // decrement weak reference count
1193         if (_MT_DECR(_Weaks) == 0) {
1194             _Delete_this();
1195         }
1196     }
1197 
1198     long _Use_count() const noexcept {
1199         return static_cast<long>(_Uses);
1200     }
1201 
1202     virtual void* _Get_deleter(const type_info&) const noexcept {
1203         return nullptr;
1204     }
1205 };
