2100 template <class _Ty>
2101 class _Ref_count_obj2 : public _Ref_count_base { // handle reference counting for object in control block, no allocator
2102 public:
2103     template <class... _Types>
2104     explicit _Ref_count_obj2(_Types&&... _Args) : _Ref_count_base() {
2105 #if _HAS_CXX20
2106         if constexpr (sizeof...(_Types) == 1 && (is_same_v<_For_overwrite_tag, remove_cvref_t<_Types>> && ...)) {
2107             _STD _Default_construct_in_place(_Storage._Value);
2108             ((void)_Args, ...);
2109         }
2110         else
2111 #endif // _HAS_CXX20
2112         {
2113             _STD _Construct_in_place(_Storage._Value, _STD forward<_Types>(_Args)...);
2114         }
2115     }
2116 
2117     ~_Ref_count_obj2() noexcept override { // TRANSITION, should be non-virtual
2118         // nothing to do, _Storage._Value was already destroyed in _Destroy
2119 
2120         // N4950 [class.dtor]/7:
2121         // "A defaulted destructor for a class X is defined as deleted if:
2122         // X is a union-like class that has a variant member with a non-trivial destructor"
2123     }
2124 
2125     union {
2126         _Wrap<remove_cv_t<_Ty>> _Storage;
2127     };
2128 
2129 private:
2130     void _Destroy() noexcept override { // destroy managed resource
2131         _STD _Destroy_in_place(_Storage._Value);
2132     }
2133 
2134     void _Delete_this() noexcept override { // destroy self
2135         delete this;
2136     }
2137 };
